INSERT INTO admin_idp.legal_document (id, doc_type, language, version, content, published_at, published_by)
SELECT gen_random_uuid()::text, 'PRIVACY', 'EN',
       COALESCE((SELECT max(version) FROM admin_idp.legal_document WHERE doc_type = 'PRIVACY' AND language = 'EN'), 0) + 1,
       $legal$This Privacy Policy explains what data VYRA collects, what it is used for, who can access it and your rights over it.

1. Data We Collect
Account data: first name, last name, email address, phone number and PIN (stored as a hash, so nobody can read it). Data you record: transactions, categories, budgets, balances, mood check-ins and journal notes, habits and goals. Preferences and device: language, theme, currency, time zone, notification settings and the device notification token when notifications are on. Technical data: login times, IP address and security logs. Problem reports you send.

2. How We Use Data
Data is used to run VYRA's features (recording, balances, summaries, trends and insights), to send OTP codes and service emails, to send the reminders and notifications you turn on, to protect your account from fraud and unauthorised access, and to answer reports and support requests. We do not use your data for advertising and we never sell it.

3. Data Security
Connections to the app are protected by TLS (HTTPS) encryption. Journal notes are stored encrypted, the PIN and session tokens are stored as hashes, and admin access is limited by role and recorded in an audit log. No system is completely immune, so please help us by keeping your PIN and OTP confidential.

4. Third-Party Service Providers
We do not sell, rent or trade your personal data. Data is only processed by the infrastructure providers we use to run the service, as far as needed: server and database hosting, the email delivery provider (for OTP and service emails) and Google's Firebase Cloud Messaging (for notifications, when on). We may also disclose data when required by law.

5. Your Rights
You can view and update your profile in the app, download a copy of all your data through Profile → Export Data (the link is emailed to you and works for 24 hours), manage notifications, and delete your account through Profile → Delete Account with your PIN and an OTP. For other questions or requests about your data, contact us through the email in Profile → Help.

6. Retention and Account Deletion
Data is kept while your account is active. When you delete your account, it is deactivated at once: you can no longer log in and every session ends. The account data is kept in an inactive state for security, audit and recovery through support. If you want your data erased permanently, send a request to the support email.

7. Access by VYRA Administrators
Only the VYRA Super Admin has full access to your data, including transaction records and balances, mood check-ins and journal notes (stored encrypted), habits and goals. This access is used for operations, support, security and abuse prevention; every time a member's transactions or the transaction, mood, habit and goal reports are opened, the access is recorded in an audit log. Administrators with other roles (Administrator, Operator, Viewer) only see your profile and contact data, the problem reports you send and aggregate statistics without per-member detail. They never see your finance records or wellbeing data.

8. Upcoming Features and Policy Changes
The weekly AI reflection is still coming soon. When it arrives, it will only run with your consent and will not send your journal, names or amounts. We may update this policy. The latest version is always available in the VYRA app and website, and important changes are announced in the app.$legal$, now(), 'SYSTEM'
WHERE NOT EXISTS (
    SELECT 1 FROM admin_idp.legal_document d
    WHERE d.doc_type = 'PRIVACY' AND d.language = 'EN'
      AND d.version = (SELECT max(version) FROM admin_idp.legal_document WHERE doc_type = 'PRIVACY' AND language = 'EN')
      AND d.content = $legal$This Privacy Policy explains what data VYRA collects, what it is used for, who can access it and your rights over it.

1. Data We Collect
Account data: first name, last name, email address, phone number and PIN (stored as a hash, so nobody can read it). Data you record: transactions, categories, budgets, balances, mood check-ins and journal notes, habits and goals. Preferences and device: language, theme, currency, time zone, notification settings and the device notification token when notifications are on. Technical data: login times, IP address and security logs. Problem reports you send.

2. How We Use Data
Data is used to run VYRA's features (recording, balances, summaries, trends and insights), to send OTP codes and service emails, to send the reminders and notifications you turn on, to protect your account from fraud and unauthorised access, and to answer reports and support requests. We do not use your data for advertising and we never sell it.

3. Data Security
Connections to the app are protected by TLS (HTTPS) encryption. Journal notes are stored encrypted, the PIN and session tokens are stored as hashes, and admin access is limited by role and recorded in an audit log. No system is completely immune, so please help us by keeping your PIN and OTP confidential.

4. Third-Party Service Providers
We do not sell, rent or trade your personal data. Data is only processed by the infrastructure providers we use to run the service, as far as needed: server and database hosting, the email delivery provider (for OTP and service emails) and Google's Firebase Cloud Messaging (for notifications, when on). We may also disclose data when required by law.

5. Your Rights
You can view and update your profile in the app, download a copy of all your data through Profile → Export Data (the link is emailed to you and works for 24 hours), manage notifications, and delete your account through Profile → Delete Account with your PIN and an OTP. For other questions or requests about your data, contact us through the email in Profile → Help.

6. Retention and Account Deletion
Data is kept while your account is active. When you delete your account, it is deactivated at once: you can no longer log in and every session ends. The account data is kept in an inactive state for security, audit and recovery through support. If you want your data erased permanently, send a request to the support email.

7. Access by VYRA Administrators
Only the VYRA Super Admin has full access to your data, including transaction records and balances, mood check-ins and journal notes (stored encrypted), habits and goals. This access is used for operations, support, security and abuse prevention; every time a member's transactions or the transaction, mood, habit and goal reports are opened, the access is recorded in an audit log. Administrators with other roles (Administrator, Operator, Viewer) only see your profile and contact data, the problem reports you send and aggregate statistics without per-member detail. They never see your finance records or wellbeing data.

8. Upcoming Features and Policy Changes
The weekly AI reflection is still coming soon. When it arrives, it will only run with your consent and will not send your journal, names or amounts. We may update this policy. The latest version is always available in the VYRA app and website, and important changes are announced in the app.$legal$);

-- 3. Announcement about the agreement texts (banner in the app for 30 days, sent once as a notification).
INSERT INTO admin_idp.announcement (id, title, body, language, status, starts_at, ends_at, published_at, created_at, created_by)
SELECT gen_random_uuid()::text, t.title, t.body, t.language, 'PUBLISHED', now(), now() + interval '30 days', now(), now(), 'SYSTEM'
FROM (VALUES
    ('ID', 'Syarat & Ketentuan dan Kebijakan Privasi VYRA',
     'Kami memperbarui Syarat & Ketentuan dan Kebijakan Privasi VYRA. Isinya menjelaskan bahwa VYRA adalah aplikasi gratis untuk mencatat keuangan dan wellbeing tanpa uang sungguhan, cara kami menjaga dan memakai data Anda, hak Anda untuk mengekspor data dan menghapus akun, serta akses Super Admin VYRA ke data akun (transaksi, mood dan jurnal, kebiasaan, goal) untuk operasional, dukungan, dan keamanan. Admin dengan peran lain tidak dapat melihat data tersebut. Baca selengkapnya di Profil → Syarat & Ketentuan dan Profil → Kebijakan Privasi.'),
    ('EN', 'VYRA Terms & Conditions and Privacy Policy',
     'We updated the VYRA Terms & Conditions and Privacy Policy. They explain that VYRA is a free app for recording your finances and wellbeing without real money, how we protect and use your data, your right to export your data and delete your account, and the VYRA Super Admin''s access to account data (transactions, mood and journal, habits, goals) for operations, support and security. Administrators with other roles cannot see this data. Read more in Profile → Terms & Conditions and Profile → Privacy Policy.')
) AS t(language, title, body)
WHERE NOT EXISTS (SELECT 1 FROM admin_idp.announcement a WHERE a.title = t.title AND a.deleted_at IS NULL);
